// ❌ OLD: Injecting raw @Req() exposes the entire underlying Express request,
// breaks unit testing (requires mocking huge Request objects), and loses type safety.
import { Controller, Get, Req, UseGuards } from '@nestjs/common';
import { AuthGuard } from './auth.guard';

@Controller('profile')
export class ProfileController {
  @Get()
  @UseGuards(AuthGuard)
  getProfile(@Req() req: any) {
    const userId = req.user.id;
    return { id: userId };
  }
}

import { Controller, Get, UseGuards, createParamDecorator, ExecutionContext, ParseIntPipe } from '@nestjs/common';
import { AuthGuard } from './auth.guard';

// ✅ NEW: Reusable custom parameter decorator
export const User = createParamDecorator(
  (data: string | undefined, ctx: ExecutionContext) => {
    const request = ctx.switchToHttp().getRequest();
    const user = request.user;
    return data ? user?.[data] : user;
  },
);

@Controller('profile')
export class ProfileController {
  @Get()
  @UseGuards(AuthGuard)
  getProfile(@User('id') userId: string) {
    // ✅ Unit testing this method requires passing a simple string, not an Express mock!
    return { id: userId };
  }
}
